import React, { useState } from "react";
import "../App.css";

function AddListingPage() {
  const [step, setStep] = useState(1);
  const [listingType, setListingType] = useState({
    purpose: "", // Sell or Rent
    propertyType: "", // Home, Office, Hostel/Hotel, etc.
  });

  const [form, setForm] = useState({
    title: "",
    description: "",
    price: "",
    location: "",
    bedrooms: "",
    bathrooms: "",
    area: "",
    amenities: "",
    image: null,
  });

  // Handle first step selection
  const handleTypeChange = (e) => {
    const { name, value } = e.target;
    setListingType({ ...listingType, [name]: value });
  };

  const handleNext = () => {
    if (listingType.purpose && listingType.propertyType) {
      setStep(2);
    } else {
      alert("Please select purpose and property type");
    }
  };

  // Handle form changes
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setForm({ ...form, [name]: files ? files[0] : value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const finalData = { ...listingType, ...form };
    console.log("Listing added:", finalData);
    alert("Your listing has been added successfully!");
  };

  return (
    <div className="add-listing-container">
      {step === 1 && (
        <div className="form-step">
          <h2 className="form-title">Step 1: Select Purpose & Property Type</h2>
          <label>Purpose</label>
          <select name="purpose" value={listingType.purpose} onChange={handleTypeChange} required>
            <option value="">Select Purpose</option>
            <option value="Sell">Sell</option>
            <option value="Rent">Rent</option>
          </select>

          <label>Property Type</label>
          <select name="propertyType" value={listingType.propertyType} onChange={handleTypeChange} required>
            <option value="">Select Property Type</option>
            <option value="Home">Home</option>
            <option value="Office">Office</option>
            <option value="Hostel/Hotel">Hostel/Hotel Stay</option>
            <option value="Shop">Shop</option>
            <option value="Land">Land</option>
          </select>

          <button className="submit-btn" onClick={handleNext}>
            Next
          </button>
        </div>
      )}

      {step === 2 && (
        <form className="add-listing-form" onSubmit={handleSubmit}>
          <h2 className="form-title">Step 2: Fill Listing Details</h2>

          <label>Title</label>
          <input
            type="text"
            name="title"
            value={form.title}
            onChange={handleChange}
            placeholder="Enter title for your listing"
            required
          />

          <label>Description</label>
          <textarea
            name="description"
            value={form.description}
            onChange={handleChange}
            placeholder="Describe your property"
            required
          />

          <label>Price (₹)</label>
          <input
            type="number"
            name="price"
            value={form.price}
            onChange={handleChange}
            placeholder={listingType.purpose === "Rent" ? "Monthly Rent" : "Sale Price"}
            required
          />

          <label>Location</label>
          <input
            type="text"
            name="location"
            value={form.location}
            onChange={handleChange}
            placeholder="City, State"
            required
          />

          {/* Conditional Fields for Home/Office/Hostel */}
          {(listingType.propertyType === "Home" || listingType.propertyType === "Office") && (
            <>
              <label>Bedrooms</label>
              <input
                type="number"
                name="bedrooms"
                value={form.bedrooms}
                onChange={handleChange}
                placeholder="Number of bedrooms"
              />

              <label>Bathrooms</label>
              <input
                type="number"
                name="bathrooms"
                value={form.bathrooms}
                onChange={handleChange}
                placeholder="Number of bathrooms"
              />

              <label>Area (sq ft)</label>
              <input
                type="number"
                name="area"
                value={form.area}
                onChange={handleChange}
                placeholder="Enter area in sq ft"
              />
            </>
          )}

          {listingType.propertyType === "Hostel/Hotel" && (
            <>
              <label>Number of Rooms</label>
              <input
                type="number"
                name="bedrooms"
                value={form.bedrooms}
                onChange={handleChange}
                placeholder="Number of rooms available"
              />

              <label>Capacity per Room</label>
              <input
                type="number"
                name="bathrooms"
                value={form.bathrooms}
                onChange={handleChange}
                placeholder="Capacity per room"
              />
            </>
          )}

          <label>Amenities</label>
          <input
            type="text"
            name="amenities"
            value={form.amenities}
            onChange={handleChange}
            placeholder="Pool, Parking, WiFi, etc."
          />

          <label>Upload Image</label>
          <input type="file" name="image" accept="image/*" onChange={handleChange} />

          <button type="submit" className="submit-btn">
            Add Listing
          </button>
        </form>
      )}
    </div>
  );
}

export default AddListingPage;
